end_time = datetime(2026, 10, 16, 13, 35, 0)

total_points = len(coordinates)
total_duration = (end_time - start_time).total_seconds()
time_step = total_duration / max(1, (total_points - 1))

with open('vehicle_gps_data.csv', mode='w', newline='', encoding='utf-8') as file:
    writer = csv.writer(file)
    # Header format requested: vehicle_id, latitude, longitude, timestamp, speed
    writer.writerow(['vehicle_id', 'latitude', 'longitude', 'timestamp', 'speed'])
    
    for i, (lat, lng) in enumerate(coordinates):
        current_time = start_time + timedelta(seconds=i * time_step)
        timestamp_str = current_time.strftime('%Y-%m-%d %H:%M:%S')
        speed = 35.0  # Default speed value
        writer.writerow([vehicle_id, lat, lng, timestamp_str, speed])

print("Successfully created!")